    h1: { en: "Core Home Maintenance — AC, Plumbing, Electrical &amp; Wall Painting in Dubai, Sharjah &amp; Abu Dhabi", ar: "الصيانة المنزلية الأساسية — تكييف، سباكة، كهرباء ودهان في دبي والشارقة وأبوظبي" },
